export default function Icon({ name, ...props }: IconProps) {
  switch (name) {
    case "user":
      return <User {...props} />;
    case "search":
      return <Search {...props} />;
    case "google-play":
      return <GooglePlay {...props} />;
    case "apple-store":
      return <AppleStore {...props} />;
    case "secure":
      return <Secure {...props} />;
    case "fast":
      return <Fast {...props} />;
    case "dollar":
      return <Dollar {...props} />;
    case "check":
      return <Check {...props} />;
    case "send":
      return <Send {...props} />;
    case "transaction-status":
      return <TransactionStatus {...props} />;
    case "people":
      return <People {...props} />;
    case "linkedin":
      return <LinkedIn {...props} />;
    case "instagram":
      return <Instagram {...props} />;
    case "facebook":
      return <FaceBook {...props} />;
    default:
      return null;
  }
}
